VERSION = "2.0.4"
MONTHS = {m:i for i,m in enumerate(['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'],1)}
KNOWN_METHODS = {"GET","POST","PUT","DELETE","HEAD","OPTIONS","PATCH","CONNECT","TRACE"}
DEFAULT_FIELDS = ['date','status','ref','path']
