HELP_TEXT = f"""                    rhit {VERSION}

Rhit analyzes your nginx logs.

Complete documentation at https://dystroy.org/rhit

Usage:  rhit [options] [FILES]

• FILES : The log file or folder to analyze. It
  not provided, logs will be opened at their
  standard location

Options:
  --help                 Print help information
  --version              Print the version
  --color <color>        Whether to have styles and colors [auto, yes, no]
  -k, --key <KEY>        Key used in sorting and histogram, either hits or bytes [default: hits]
  -l, --length <LENGTH>  Detail level, from 0 to 6 [default: 1]
  -f, --fields <FIELDS>  Comma separated list of hit fields to display
  -c, --changes          Add tables with more popular and less popular entries
  -d, --date <DATE>      Filter the dates on a precise day or in an inclusive range
  -i, --ip <IP>          Ip address to filter by. May be negated with a !
  -m, --method <METHOD>  HTTP method to filter by. Make it negative with a !
  -p, --path <PATH>      Pattern for path filtering
  -r, --referer <REF>    Referrer filter
  -s, --status <STATUS>  Comma separated list of statuses or ranges to filter by
  -t, --time <TIME>      Filter the time of the day
  -a, --all              Show all paths, including resources
  --no-name-check        Try to open all files, whatever their names
  -o, --output <OUTPUT>  Output: tables, csv, json, or raw [default: tables]
  --silent-load          Don't print anything during load
"""

def cli_error(msg):
    raise CliError(msg, 2)

def normalize_output(v):
    mp={'r':'raw','raw':'raw','c':'csv','csv':'csv','j':'json','json':'json','t':'tables','tables':'tables'}
    if v not in mp:
        cli_error(f"error: invalid value '{v}' for '--output <OUTPUT>': unrecognized output \"{v}\"")
    return mp[v]

def normalize_key(v):
    mp={'h':'hits','hits':'hits','b':'bytes','bytes':'bytes'}
    if v not in mp:
        cli_error(f"error: invalid value '{v}' for '--key <KEY>': unrecognized key \"{v}\"")
    return mp[v]

def parse_args(argv):
    opts=Opts(paths=[])
    i=0
    stop=False
    while i < len(argv):
        a=argv[i]
        if stop:
            opts.paths.append(a); i+=1; continue
        if a=='--': stop=True; i+=1; continue
        if a=='--help':
            print(HELP_TEXT); sys.exit(0)
        if a=='--version':
            print(f"rhit {VERSION}"); sys.exit(0)
        def need(opt):
            nonlocal i
            if i+1>=len(argv): cli_error(f"error: a value is required for '{opt} <VALUE>' but none was supplied")
            i+=1; return argv[i]
        if a in ('-o','--output'):
            opts.output=normalize_output(need('--output'))
        elif a.startswith('--output='):
