            opts.changes=True
        elif a in ('-d','--date'):
            opts.date_filter=need('--date')
        elif a.startswith('--date='):
            opts.date_filter=a.split('=',1)[1]
        elif a in ('-i','--ip'):
            opts.ip_filter=need('--ip')
        elif a.startswith('--ip='):
            opts.ip_filter=a.split('=',1)[1]
        elif a in ('-m','--method'):
            opts.method_filter=need('--method')
        elif a.startswith('--method='):
            opts.method_filter=a.split('=',1)[1]
        elif a in ('-p','--path'):
            opts.path_filter=need('--path')
        elif a.startswith('--path='):
            opts.path_filter=a.split('=',1)[1]
        elif a in ('-r','--referer','--referrer'):
            opts.referer_filter=need('--referer')
        elif a.startswith('--referer=') or a.startswith('--referrer='):
            opts.referer_filter=a.split('=',1)[1]
        elif a in ('-s','--status'):
            opts.status_filter=need('--status')
        elif a.startswith('--status='):
            opts.status_filter=a.split('=',1)[1]
        elif a in ('-t','--time'):
            opts.time_filter=need('--time')
        elif a.startswith('--time='):
            opts.time_filter=a.split('=',1)[1]
        elif a in ('-a','--all'):
            opts.all_paths=True
        elif a=='--no-name-check':
            opts.no_name_check=True
        elif a=='--silent-load':
            opts.silent_load=True
        elif a=='--color':
            opts.color=need('--color')
        elif a.startswith('--color='):
            opts.color=a.split('=',1)[1]
        elif a.startswith('-'):
            cli_error(f"error: unexpected argument '{a}' found\n\n  tip: to pass '{a}' as a value, use '-- {a}'\n\nUsage: executable [OPTIONS] [FILES]...")
        else:
            opts.paths.append(a)
        i+=1
    return opts

def parse_nginx_line(line):
    line=line.rstrip('\n')
    m=re.match(r'^(\S+)\s+\S+\s+\S+\s+\[([^\]]+)\]\s+"([^"]*)"\s+(\d{3})\s+(\d+)\s+"([^"]*)"', line)
    if not m:
        return None
    ip, dts, req, status, bytes_s, ref = m.groups()
    dm=re.match(r'^(\d{1,2})/([A-Za-z]{3})/(\d{4}):(\d{2}):(\d{2}):(\d{2})', dts)
    if not dm or dm.group(2) not in MONTHS:
        return None
    day, mon, year, hh, mm, ss = dm.groups()
    try:
        dt=datetime(int(year), MONTHS[mon], int(day), int(hh), int(mm), int(ss))
    except ValueError:
        return None
    parts=req.split()
    if len(parts)>=2:
        meth=parts[0]
        path=parts[1]
        if meth not in KNOWN_METHODS:
            meth='other'
    else:
        meth='none'
        path=req
    return Hit(line, ip, dt, dt.strftime('%Y/%m/%d'), dt.strftime('%H:%M:%S'), meth, path, status, int(bytes_s), ref)

def accepted_name(name):
    return name.startswith('access.log')

def collect_files(paths, no_name_check=False):
    default=False
    if not paths:
        paths=['/var/log/nginx']; default=True
    files=[]
    for p in paths:
        if not os.path.exists(p):
            if default and p=='/var/log/nginx':
                raise RunError('DEFAULT_MISSING')
            raise RunError(f'PathNotFound("{p}")')
        if os.path.isdir(p):
            names=sorted(os.listdir(p))
            for n in names:
                fp=os.path.join(p,n)
                if os.path.isfile(fp) and (no_name_check or accepted_name(n)):
                    files.append(fp)
        elif os.path.isfile(p):
            files.append(p)
    return files

def read_hits(files):
    hits=[]
    for fp in files:
        try:
            opener=gzip.open if fp.endswith('.gz') else open
            with opener(fp, 'rt', errors='replace') as f:
                for line in f:
                    h=parse_nginx_line(line)
                    if h is not None:
                        hits.append(h)
        except Exception:
            # unreadable/corrupt files are simply ineffective for this small reimplementation
            pass
    return hits

def parse_fields(spec):
    fields=list(DEFAULT_FIELDS)
    if not spec:
        return fields
    s=spec.strip()
    if not s:
        return fields
    # first token may replace the default list
    pos=0
    if s[0] not in '+-':
        # consume until first + or - outside simple text; commas also separate replacement fields
        cut=len(s)
        for j,ch in enumerate(s):
            if ch in '+-': cut=j; break
        first=s[:cut]
        fields=[]
        for part in re.split(r'[, ]+', first):
            if not part: continue
            if part in ('a','all'):
                fields=list(ALL_FIELDS)
            else:
                f=FIELD_ALIASES.get(part)
                if not f:
                    cli_error(f"error: invalid value '{spec}' for '--fields <FIELDS>': unrecognized field start '{part[0]}'")
                if f not in fields: fields.append(f)
        pos=cut
    while pos < len(s):
        op=s[pos]; pos+=1
        cut=len(s)
        for j in range(pos,len(s)):
            if s[j] in '+-': cut=j; break
        token=s[pos:cut].strip(', ')
        sub=[]
        if token in ('a','all'):
            sub=list(ALL_FIELDS)
        else:
            for part in re.split(r'[, ]+', token):
                if not part: continue
                f=FIELD_ALIASES.get(part)
                if not f:
                    cli_error(f"error: invalid value '{spec}' for '--fields <FIELDS>': unrecognized field start '{part[0]}'")
                sub.append(f)
        if op=='+':
            for f in sub:
                if f in fields: fields.remove(f)
                fields.append(f)
        elif op=='-':
            for f in sub:
                if f in fields: fields.remove(f)
        pos=cut
    return fields

def regex_match(pattern, text):
    try:
        return re.search(pattern, text) is not None
    except re.error as e:
        raise RunError(f"StrFilter(InvalidRegex(Syntax(\nregex parse error:\n    {pattern}\nerror: {e}\n)))")

def simple_regex_filter(pattern, text):
    neg=pattern.startswith('!')
    pat=pattern[1:] if neg else pattern
    res=regex_match(pat, text)
    return (not res) if neg else res

class ExprParser:
    def __init__(self, s):
        self.s=s; self.i=0
    def skip(self):
        while self.i<len(self.s) and self.s[self.i].isspace(): self.i+=1
    def parse(self):
        node=self.parse_or(); self.skip(); return node
    def parse_or(self):
        node=self.parse_and()
        while True:
            self.skip()
            if self.i<len(self.s) and self.s[self.i]=='|':
                self.i+=1; right=self.parse_and(); node=('or',node,right)
            else: return node
    def parse_and(self):
        node=self.parse_not()
        while True:
            self.skip()
            if self.i<len(self.s) and self.s[self.i] in '&,':
                self.i+=1; right=self.parse_not(); node=('and',node,right)
            else: return node
    def parse_not(self):
        self.skip()
        if self.i<len(self.s) and self.s[self.i]=='!':
            self.i+=1; return ('not', self.parse_not())
        return self.parse_atom()
    def parse_atom(self):
        self.skip()
        if self.i<len(self.s) and self.s[self.i]=='(':
            self.i+=1; node=self.parse_or(); self.skip()
            if self.i<len(self.s) and self.s[self.i]==')': self.i+=1
            return node
        start=self.i
        while self.i<len(self.s):
            ch=self.s[self.i]
            if ch in ',&|)': break
            self.i+=1
        pat=self.s[start:self.i].strip()
        return ('re', pat)

def eval_expr(node, text):
    typ=node[0]
    if typ=='re': return regex_match(node[1], text)
    if typ=='not': return not eval_expr(node[1], text)
    if typ=='and': return eval_expr(node[1], text) and eval_expr(node[2], text)
    if typ=='or': return eval_expr(node[1], text) or eval_expr(node[2], text)
    return True

def pattern_filter(pattern, text):
    # Regex metacharacters like | and (...) are regex unless clearly separated as boolean syntax.
    if ',' in pattern or re.search(r'\s[&|]\s', pattern) or re.search(r'(^|[\s(])![^\s]*', pattern):
        # turn whitespace separated operators into parseable form. Parenthesized regexes without spaces
        # won't normally come here.
        return eval_expr(ExprParser(pattern).parse(), text)
    return simple_regex_filter(pattern, text)

def method_value(v):
    neg=v.startswith('!')
    x=v[1:] if neg else v
    xu=x.upper()
    if x.lower() in ('none','other'):
        val=x.lower()
    elif xu in KNOWN_METHODS:
        val=xu
    else:
        val='other'
    return neg,val

def status_token_match(tok, status):
    st=int(status)
    if re.fullmatch(r'\dxx', tok):
        return st//100 == int(tok[0])
    if re.fullmatch(r'\d{3}-\d{3}', tok):
        a,b=map(int,tok.split('-'))
        return a<=st<=b
    if re.fullmatch(r'\d{3}', tok):
        return st==int(tok)
    return False

def status_filter(pattern, status):
    toks=[t.strip() for t in pattern.split(',') if t.strip()]
    positives=[]; negatives=[]
    for t in toks:
        if t.startswith('!'): negatives.append(t[1:])
        else: positives.append(t)
    if positives:
        ok=any(status_token_match(t,status) for t in positives)
    else:
        ok=True
    if ok and negatives:
        if any(status_token_match(t,status) for t in negatives): ok=False
    return ok

def parse_date_bound(s, is_end=False, default_year=None):
    # returns datetime lower/upper for a prefix date/time. Supports Y, Y/M, Y/M/D, M/D shortcuts.
    if 'T' in s:
        ds,ts=s.split('T',1)
    else:
        ds,ts=s,''
    parts=[p for p in ds.split('/') if p!='']
    if len(parts)==0: raise RunError('DateTime(IntExpected(ParseIntError { kind: Empty }))')
    try:
        nums=list(map(int,parts))
    except Exception:
        raise RunError('DateTime(IntExpected(ParseIntError { kind: InvalidDigit }))')
    if len(nums)==1:
        y=nums[0]; mo=1; da=1; gran='year'
    elif len(nums)==2:
        if nums[0]>31:
            y,mo=nums; da=1; gran='month'
        else:
            if default_year is None: default_year=datetime.now().year
            y=default_year; mo,da=nums; gran='day'
    else:
        y,mo,da=nums[:3]; gran='day'
    hour=0; minute=0; sec=0; tgran=None
    if ts:
        tp=ts.split(':')
        try: tn=list(map(int,tp))
        except Exception: raise RunError('DateTime(IntExpected(ParseIntError { kind: InvalidDigit }))')
        hour=tn[0] if len(tn)>0 else 0; minute=tn[1] if len(tn)>1 else 0; sec=tn[2] if len(tn)>2 else 0
        tgran=['hour','minute','second'][min(len(tn),3)-1]
    try:
        start=datetime(y,mo,da,hour,minute,sec)
    except Exception:
        raise RunError('DateTime(IntExpected(ParseIntError { kind: Empty }))')
    if not is_end:
        return start
    if ts:
        if tgran=='hour': return start.replace(minute=59,second=59)
        if tgran=='minute': return start.replace(second=59)
        return start
    if gran=='year': return datetime(y,12,31,23,59,59)
    if gran=='month':
        if mo==12: nxt=datetime(y+1,1,1)
        else: nxt=datetime(y,mo+1,1)
        return nxt-timedelta(seconds=1)
    return datetime(y,mo,da,23,59,59)

def date_filter_func(pattern, hits):
    years={h.dt.year for h in hits}
    default_year=next(iter(years)) if len(years)==1 else None
    neg=pattern.startswith('!')
    p=pattern[1:] if neg else pattern
    op=None
    if p.startswith(('>','<')):
        op=p[0]; p=p[1:]
    if '-' in p and not p.startswith('-'):
        a,b=p.split('-',1)
        lo=parse_date_bound(a, False, default_year); hi=parse_date_bound(b, True, default_year)
        def f(h): return lo<=h.dt<=hi
    elif op=='>':
        hi=parse_date_bound(p, True, default_year)
        def f(h): return h.dt>hi
    elif op=='<':
        lo=parse_date_bound(p, False, default_year)
        def f(h): return h.dt<lo
    else:
        lo=parse_date_bound(p, False, default_year); hi=parse_date_bound(p, True, default_year)
        def f(h): return lo<=h.dt<=hi
    return lambda h: (not f(h)) if neg else f(h)

def parse_hms(s):
    parts=s.split(':')
    nums=list(map(int,parts))
    h=nums[0]; m=nums[1] if len(nums)>1 else 0; sec=nums[2] if len(nums)>2 else 0
    return h*3600+m*60+sec

def time_filter_func(pattern):
    if pattern.startswith('>'):
        val=parse_hms(pattern[1:]); return lambda h: parse_hms(h.time_s)>val
    if pattern.startswith('<'):
        val=parse_hms(pattern[1:]); return lambda h: parse_hms(h.time_s)<val
    if '-' in pattern:
        a,b=pattern.split('-',1); va=parse_hms(a); vb=parse_hms(b); return lambda h: va<=parse_hms(h.time_s)<=vb
    val=parse_hms(pattern); return lambda h: parse_hms(h.time_s)==val

def apply_filters(hits, opts):
    filtered=list(hits)
    summaries=[]
    filter_defs=[]
    if opts.date_filter: filter_defs.append(('date', opts.date_filter, date_filter_func(opts.date_filter, hits)))
    if opts.time_filter: filter_defs.append(('time', opts.time_filter, time_filter_func(opts.time_filter)))
    if opts.ip_filter:
        p=opts.ip_filter; filter_defs.append(('IP address', p, lambda h,p=p: simple_regex_filter(p,h.remote_addr)))
    if opts.method_filter:
        neg,val=method_value(opts.method_filter)
        filter_defs.append(('method', opts.method_filter, lambda h,neg=neg,val=val: (h.method!=val if neg else h.method==val)))
    if opts.path_filter:
        p=opts.path_filter; filter_defs.append(('path', p, lambda h,p=p: pattern_filter(p,h.path)))
    if opts.referer_filter:
        p=opts.referer_filter; filter_defs.append(('referrer', p, lambda h,p=p: pattern_filter(p,h.referer)))
    if opts.status_filter:
        p=opts.status_filter; filter_defs.append(('status', p, lambda h,p=p: status_filter(p,h.status)))
    for name,pat,func in filter_defs:
        before=len(filtered)
        filtered=[h for h in filtered if func(h)]
        removed = 0.0 if before==0 else (before-len(filtered))*100.0/before
        summaries.append((name,pat,removed))
    return filtered, summaries

def csv_quote(s):
    return '"' + s.replace('"','""') + '"'

def output_csv(hits):
    print('date,time,remote address,method,path,status,bytes sent,referer')
    for h in hits:
        print(f'{h.date_s},{h.time_s},{h.remote_addr},{h.method},{csv_quote(h.path)},{h.status},{h.bytes_sent},{csv_quote(h.referer)}')

def output_json(hits):
    arr=[]
    for h in hits:
        arr.append(OrderedDict([
            ('date', h.date_s), ('time', h.time_s), ('remote_addr', h.remote_addr),
            ('method', h.method), ('path', h.path), ('status', h.status),
            ('bytes_sent', h.bytes_sent), ('referer', h.referer)
        ]))
    print(json.dumps(arr, indent=2))

def output_raw(hits):
    for h in hits: print(h.raw)

def daterange(d1,d2):
    cur=d1
    while cur<=d2:
        yield cur
        cur += timedelta(days=1)

def key_value(item, key):
    return item['bytes'] if key=='bytes' else item['hits']

def row_limit(length):
    if length<=0: return 10
    return 50*length

def pct_str(hits,total):
    if total<=0: return '0.0%'
    return f'{hits*100.0/total:.1f}%'

def make_table(headers, rows, aligns=None):
    if aligns is None: aligns=['left']*len(headers)
    widths=[]
    for c,h in enumerate(headers):
        widths.append(max(len(str(h)), *(len(str(r[c])) for r in rows)) if rows else len(str(h)))
    def fmt_cell(s,w,align):
        s=str(s)
        if align=='right': return s.rjust(w)
        if align=='center': return s.center(w)
        return s.ljust(w)
    def border(left,mid,right): return left + mid.join('─'*w for w in widths) + right
    lines=[border('┌','┬','┐')]
    lines.append('│'+'│'.join(fmt_cell(headers[i], widths[i], 'center') for i in range(len(headers)))+'│')
    lines.append(border('├','┼','┤'))
    for r in rows:
        lines.append('│'+'│'.join(fmt_cell(r[i], widths[i], aligns[i]) for i in range(len(headers)))+'│')
    lines.append(border('└','┴','┘'))
    return '\n'.join(lines)

def bar(v,maxv,width=20):
    if maxv<=0 or v<=0: return ' '*width
    n=int(v*width/maxv)
    if n<1: n=1
    if n>width: n=width
    return '█'*n + ' '*(width-n)

def spark(vals):
    chars='▁▂▃▄▅▆▇'
    m=max(vals) if vals else 0
    out=''
    for v in vals:
        if m<=0 or v<=0: out+=' '
        else:
            idx=int((v-1)*6/m)
            if idx<0: idx=0
            if idx>6: idx=6
            out+=chars[idx]
    return out

def trend(vals):
    if len(vals)<4: return ''
    a=sum(vals[-2:])/2; b=sum(vals[-4:-2])/2
    if a>b*1.25 and a-b>0: return ' ➚ '
    if b>a*1.25 and b-a>0: return '➘ ➘'
    return ''

def count_by_date(hits):
    d=defaultdict(lambda:{'hits':0,'bytes':0})
    for h in hits:
        da=h.dt.date(); d[da]['hits']+=1; d[da]['bytes']+=h.bytes_sent
    return d

def date_table(hits, original_hits, opts, has_date_filter):
    if not hits and not original_hits: return ''
    source=hits if has_date_filter and hits else original_hits
    if not source: return ''
    dmin=min(h.dt.date() for h in source); dmax=max(h.dt.date() for h in source)
    counts=count_by_date(hits)
    vals=[counts[da][opts.key] for da in daterange(dmin,dmax)]
    maxv=max(vals) if vals else 0
    head=f"0{' '*(18-len(str(maxv)))}{maxv}" if len(str(maxv))<19 else str(maxv)
    rows=[]
    for da in daterange(dmin,dmax):
        c=counts[da]
        rows.append([da.strftime('%Y/%m/%d'), str(c['hits']).rjust(4), str(c['bytes']).rjust(5), bar(c[opts.key], maxv, 20)])
    return make_table(['date','hits','bytes',head], rows, ['left','right','right','left'])

def time_table(hits, opts):
    counts=[{'hits':0,'bytes':0} for _ in range(24)]
    for h in hits:
        counts[h.dt.hour]['hits']+=1; counts[h.dt.hour]['bytes']+=h.bytes_sent
    maxv=max(c[opts.key] for c in counts) if counts else 0
    head=f"0{' '*(18-len(str(maxv)))}{maxv}" if len(str(maxv))<19 else str(maxv)
    rows=[]
    for hr,c in enumerate(counts):
        rows.append([str(hr), str(c['hits']), str(c['bytes']).rjust(5), bar(c[opts.key],maxv,20)])
    return make_table(['hour','hits','bytes',head], rows, ['left','center','right','left'])

def field_label(field):
    return {
        'status':('status','HTTP status codes'),
        'ip':('IP address','remote IP addresses'),
        'method':('method','methods'),
        'ref':('referrer','referrers'),
        'path':('path','paths'),
    }[field]

def categorical_items(hits, field, opts, date_list):
    data={}
    for h in hits:
        if field=='status': val=h.status
        elif field=='ip': val=h.remote_addr
        elif field=='method': val=h.method
        elif field=='ref':
            val=h.referer
            if val=='-': continue
        elif field=='path':
            val=h.path
            if not opts.all_paths and RESOURCE_RE.search(val): continue
        else: continue
        if val not in data:
            data[val]={'value':val,'hits':0,'bytes':0,'days':defaultdict(lambda:{'hits':0,'bytes':0})}
        it=data[val]; it['hits']+=1; it['bytes']+=h.bytes_sent
        da=h.dt.date(); it['days'][da]['hits']+=1; it['days'][da]['bytes']+=h.bytes_sent
    items=list(data.values())
    items.sort(key=lambda it:(-key_value(it,opts.key), -it['bytes'], it['value']))
    return items

def categorical_table(hits, original_hits, field, opts, title_override=None, sort_change=None):
    total_hits=len(hits)
    label, plural=field_label(field)
    if original_hits:
        dmin=min(h.dt.date() for h in original_hits); dmax=max(h.dt.date() for h in original_hits)
        dates=list(daterange(dmin,dmax))
    elif hits:
        dmin=min(h.dt.date() for h in hits); dmax=max(h.dt.date() for h in hits); dates=list(daterange(dmin,dmax))
    else:
        dates=[]
    items=categorical_items(hits, field, opts, dates)
    if sort_change:
        def chg(it):
            vals=[it['days'][d][opts.key] for d in dates]
            if len(vals)<4: return 0
            return sum(vals[-2:])-sum(vals[-4:-2])
        items.sort(key=lambda it: (-chg(it) if sort_change=='more' else chg(it), -key_value(it,opts.key)))
    limit=row_limit(opts.length)
    items=items[:limit]
    # Title
    if title_override:
        title=title_override
    else:
        title=f"{len(categorical_items(hits, field, opts, dates))} {plural}"
        if field=='path' and not opts.all_paths:
            title += " (excluding resources like images, css, \netc.)"
        title += ". "
    use_days = len(dates) >= 7 and field in ('path','ref','ip','method','status')
    rows=[]
    if use_days:
        for idx,it in enumerate(items,1):
            vals=[it['days'][d][opts.key] for d in dates]
            rows.append([str(idx).rjust(3), it['value'], str(it['hits']).rjust(4), str(it['bytes']).rjust(5), spark(vals), trend(vals)])
        table=make_table(['#',label,'hits','bytes','days','trend'], rows, ['right','left','right','right','left','center'])
    else:
        for idx,it in enumerate(items,1):
            rows.append([str(idx).rjust(3), it['value'], str(it['hits']).rjust(4), pct_str(it['hits'], total_hits), str(it['bytes']).rjust(5)])
        table=make_table(['#',label,'hits','%','bytes'], rows, ['right','left','right','right','right'])
    return title+'\n'+table

def output_tables(hits, original_hits, opts, summaries):
    if original_hits:
        total_bytes=sum(h.bytes_sent for h in original_hits)
        dmin=min(h.date_s for h in original_hits); dmax=max(h.date_s for h in original_hits)
        print(f"{len(original_hits)} hits and {total_bytes} from {dmin} to {dmax}")
    else:
        print("0 hits and 0")
    for name,pat,removed in summaries:
        print(f"Filtering by {name} on pattern {pat} removed {removed:.2f}% ")
        print("of total lines")
    if summaries:
        print(f" ==> hits: {len(hits)}, bytes sent: {sum(h.bytes_sent for h in hits)}")
    if not hits:
        return
    fields=parse_fields(opts.fields_spec)
    parts=[]
    if 'date' in fields:
        parts.append(date_table(hits, original_hits, opts, opts.date_filter is not None))
    if 'time' in fields:
        parts.append(time_table(hits, opts))
    for f in fields:
        if f in ('method','status','ip','ref','path'):
            parts.append(categorical_table(hits, original_hits, f, opts))
            if opts.changes and f in ('path','ref','ip'):
                base="paths" if f=='path' else ("referrers" if f=='ref' else "remote IP addresses")
                excl=" (excluding resources like \nimages, css, etc.)" if f=='path' and not opts.all_paths else ""
                parts.append(categorical_table(hits, original_hits, f, opts, f"More popular {base}{excl}", 'more'))
                parts.append(categorical_table(hits, original_hits, f, opts, f"Less popular {base}{excl}", 'less'))
    print('\n'.join(p for p in parts if p))

def main(argv):
    try:
        opts=parse_args(argv)
        files=collect_files(opts.paths, opts.no_name_check)
        if not opts.silent_load and files:
            sys.stderr.write(f"I've read {len(files)} file" + ("" if len(files)==1 else "s") + f" in \"{opts.paths[0] if opts.paths else '/var/log/nginx'}\"\n")
        hits=read_hits(files)
        if not hits:
            raise RunError('NoLogFileFound')
        filtered, summaries=apply_filters(hits, opts)
        if opts.output=='raw': output_raw(filtered)
        elif opts.output=='csv': output_csv(filtered)
        elif opts.output=='json': output_json(filtered)
        else: output_tables(filtered, hits, opts, summaries)
    except CliError as e:
        print(str(e), file=sys.stderr); return e.code
    except RunError as e:
        msg=str(e)
        if msg=='DEFAULT_MISSING':
            print('No nginx log found at default location, do you have nginx set up?', file=sys.stderr)
            print('If necessary, provide the path to the log file(s) as argument.', file=sys.stderr)
            print("More information with 'rhit --help'.", file=sys.stderr)
            print('Error: PathNotFound("/var/log/nginx")', file=sys.stderr)
        else:
            print('Error: '+msg, file=sys.stderr)
        return 1
    return 0

if __name__=='__main__':
    sys.exit(main(sys.argv[1:]))
